#include "achievement_lua.hpp"
#include <cstdio>
#include <sstream>
namespace mcl {
namespace {
std::string longString(const std::string& s){
 std::string eq;
 while(s.find("]"+eq+"]")!=std::string::npos)eq+="=";
 return "["+eq+"["+s+"]"+eq+"]";
}
std::string hex(unsigned v){char b[16];std::snprintf(b,sizeof b,"0x%X",v);return b;}
std::string list(const std::vector<unsigned>& v){
 std::string s="{";
 for(size_t i=0;i<v.size();++i){if(i)s+=",";s+=hex(v[i]);}
 return s+"}";
}
const char* kDetector=R"LUA(
-- Marvel: Crossover Legacy achievement detector (generated by the frontend for this launch).
-- Reads health, timer and stage RAM; reports results to MCL_EV.file. Nothing is written
-- to the game.
local function mcl_detector()
  local C = MCL_EV
  local machine = manager.machine
  local cpu = machine.devices[":maincpu"]
  if not cpu then return end
  local mem = cpu.spaces["program"]
  local ioport = machine.ioport
  local T = {}
  for _, tok in ipairs({"COIN1", "START1", "START2"}) do T[tok] = ioport:token_to_input_type(tok) end
  local frame = 0
  local function pressed(tok)
    if MCL_TEST_PRESSED then return MCL_TEST_PRESSED(tok, frame) end
    return ioport:type_pressed(T[tok], 0)
  end
  local held = {}
  local function edge(tok)
    local now = pressed(tok) and true or false
    local was = held[tok]
    held[tok] = now
    return now and not was
  end
  local armed, continued, credits, awaitContinue, vs = false, false, 0, 0, false
  local needZero = false -- a new run only counts once the game has reset to the first stage
  local rs, best1, hurt = "idle", 0, false
  local w1, w2, clean, streak, lastStage = 0, 0, true, 0, -1
  local function emit(kind, stage, allAlive, detail)
    local f = io.open(C.file, "a")
    if f then
      f:write(string.format("%s %d %d %d%s\n", kind, stage or -1, continued and 1 or 0,
                            allAlive and 1 or 0, detail and (" " .. detail) or ""))
      f:close()
    end
  end
  local function alive(v)
    if v > C.max then return false end
    if v == 0 then return not C.zeroDead end
    return true
  end
  local function team(slots)
    local hp, n = 0, 0
    for _, a in ipairs(slots) do
      local v = mem:read_u8(a)
      if alive(v) then hp, n = hp + v, n + 1 end
    end
    return hp, n
  end
  local function newMatch() w1, w2, clean = 0, 0, true end
  local function roundOver(result, allAlive, stage)
    if result == 0 then return end -- double KO / draw: no score
    if result == 1 then
      w1 = w1 + 1
      if not hurt and not vs then emit("perfect_round", stage) end
    elseif result == 2 then
      w2 = w2 + 1
    end
    if hurt or result ~= 1 then clean = false end
    if w1 >= C.rounds then
      if vs then emit("two_player_match", stage); vs = false
      else
        emit("match_win", stage, allAlive)
        if clean then emit("perfect_match", stage) end
        streak = streak + 1
        if streak == 5 then emit("win_streak", stage) end
        if C.bosses[stage] then emit("boss_defeated", stage, false, C.bosses[stage]) end
        if stage == C.final then emit("arcade_clear", stage); armed = false end
      end
      newMatch()
    elseif w2 >= C.rounds then
      if vs then emit("two_player_match", stage); vs = false; armed = false
      else
        emit("match_loss", stage)
        streak = 0
        awaitContinue = 60 * 30 -- the continue countdown; no START in time ends the run
      end
      newMatch()
    end
  end
  mcl_detector_sub = emu.add_machine_frame_notifier(function()
    frame = frame + 1
    local coin, start, start2 = edge("COIN1"), edge("START1"), edge("START2")
    local stage = mem:read_u8(C.stage)
    if coin then credits = credits + 1; emit("coin", stage) end
    if start and credits > 0 then
      if not armed then
        credits = credits - 1
        armed, continued, streak, awaitContinue, vs, rs = true, false, 0, 0, false, "idle"
        needZero = true
        newMatch()
        emit("start", stage)
      elseif awaitContinue > 0 then
        credits = credits - 1
        continued, awaitContinue = true, 0
        newMatch()
        emit("continue", stage)
      end
    end
    if start2 and armed and credits > 0 then credits = credits - 1; vs = true end
    if awaitContinue > 0 then
      awaitContinue = awaitContinue - 1
      if awaitContinue == 0 then armed = false end
    end
    if not armed then rs = "idle"; return end
    if stage ~= lastStage then newMatch(); lastStage = stage end
    if needZero then
      if stage ~= 0 then rs = "idle"; return end
      needZero = false
    end
    local h1, a1 = team(C.p1)
    local h2, a2 = team(C.p2)
    local t = mem:read_u8(C.timer)
    local both = a1 > 0 and a2 > 0
    if rs == "idle" then
      if both and t == C.full then rs, best1, hurt = "live", h1, false end
    elseif rs == "live" then
      if h1 < best1 then hurt = true elseif h1 > best1 then best1 = h1 end
      local result
      if a1 > 0 and a2 == 0 then result = 1
      elseif a1 == 0 and a2 > 0 then result = 2
      elseif a1 == 0 and a2 == 0 then result = 0
      elseif t == 0 then result = (h1 > h2) and 1 or ((h2 > h1) and 2 or 0) end
      if result then rs = "wait"; roundOver(result, a1 == #C.p1, stage) end
    elseif rs == "wait" then
      if not both or t ~= C.full then rs = "idle" end
    end
  end)
end
mcl_detector()
)LUA";
}
DetectorProfile detectorProfile(const std::string& g){
 DetectorProfile p;
 if(g=="xmcota"){p={g,{0xFF4191},{0xFF4591},0x90,true,0xFF4808,0x99,0xFFED5E,2,7,{{6,"juggernaut"},{7,"magneto"}}};}
 else if(g=="msh"){p={g,{0xFF4191},{0xFF4591},0x90,true,0xFF4808,0x99,0xFF4850,2,7,{{7,"thanos"}}};}
 else if(g=="xmvsf"){p={g,{0xFF4211,0xFF4A11},{0xFF4611,0xFF4E11},0x90,true,0xFF5008,0x99,0xFF5081,1,7,{{7,"apocalypse"}}};}
 else if(g=="mshvsf"){p={g,{0xFF3A51,0xFF4251},{0xFF3E51,0xFF4651},0x90,true,0xFF4808,0x99,0xFF4881,1,8,{{7,"apocalypse"},{8,"cyber_akuma"}}};}
 else if(g=="mvsc"){p={g,{0xFF3271,0xFF3A71},{0xFF3671,0xFF3E71},0x90,true,0xFF4008,0x99,0xFF4081,1,7,{{7,"onslaught"}}};}
 else if(g=="sfexp"){p={g,{0x3249E4},{0x325E58},0xC8,false,0x31D5CC,0x63,0x31D5DF,2,9,{{9,"garuda"}}};}
 else if(g=="sfex2p"){p={g,{0x2B68A8},{0x2B80AC},0xC8,false,0x2AE5BC,0x63,0x2AE5C6,2,6,{{6,"bison2"}}};}
 return p;
}
std::string buildAchievementLua(const std::string& game,const std::string& eventsFile){
 const DetectorProfile p=detectorProfile(game);
 if(p.game.empty())return {};
 std::ostringstream o;
 o<<"MCL_EV = {file="<<longString(eventsFile)<<", p1="<<list(p.p1)<<", p2="<<list(p.p2)
  <<", max="<<p.maxHealth<<", zeroDead="<<(p.zeroIsDead?"true":"false")
  <<", timer="<<hex(p.timer)<<", full="<<hex(p.timerFull)<<", stage="<<hex(p.stage)
  <<", rounds="<<p.roundsToWin<<", final="<<p.finalStage<<", bosses={";
 for(size_t i=0;i<p.bosses.size();++i){if(i)o<<", ";o<<"["<<p.bosses[i].first<<"]=\""<<p.bosses[i].second<<"\"";}
 o<<"}}\n"<<kDetector;
 return o.str();
}
std::vector<DetectedEvent> parseDetectedEvents(const std::string& text){
 std::vector<DetectedEvent> out;
 std::istringstream in(text);std::string line;
 while(std::getline(in,line)){
  std::istringstream ls(line);DetectedEvent e;int c=0,a=0;
  if(!(ls>>e.type>>e.stage>>c>>a))continue;
  if(e.type.empty()||e.type.size()>32)continue;
  e.continued=c!=0;e.allAlive=a!=0;ls>>e.detail;
  out.push_back(e);
 }
 return out;
}
}
